CREATE DATABASE IF NOT EXISTS studenthub; USE studenthub;
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE);
CREATE TABLE events(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,event_date DATE NOT NULL);
CREATE TABLE registrations(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,event_id INT NOT NULL,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(event_id) REFERENCES events(id),UNIQUE(student_id,event_id));